<section class="page-heading"><span class="eyebrow">Scheme catalogue</span><h1>Find schemes</h1><p>Search the available catalogue. Unverified records are clearly labelled.</p></section><form class="filter-bar" method="get"><input type="hidden" name="page" value="catalogue"><div class="field grow"><label for="q">Search keywords</label><input id="q" name="q" value="<?=e($search)?>" placeholder="Name or description"></div><div class="field"><label for="category">Category</label><select id="category" name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?=e($c['slug'])?>" <?=$selectedCategory===$c['slug']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></div><button class="button" type="submit">Apply filters</button></form><div class="result-count"><?=count($schemes)?> result<?=count($schemes)===1?'':'s'?> shown</div><div class="card-grid"><?php foreach($schemes as $scheme) require __DIR__.'/partials/scheme_card.php'; ?></div><?php if(!$schemes): ?><div class="empty-state"><h2>No matching schemes</h2><p>Try a different search or clear the category filter.</p></div><?php endif; ?><div class="pagination"><a href="<?=e(url('catalogue',['q'=>$search,'category'=>$selectedCategory,'p'=>max(1,$pageNo-1)]))?>">← Previous</a><span>Page <?=e($pageNo)?></span><a href="<?=e(url('catalogue',['q'=>$search,'category'=>$selectedCategory,'p'=>$pageNo+1]))?>">Next →</a></div>
